import{b as a,O as i,g as s,j as e}from"./chunks/framework.DcaUmd3X.js";const g=JSON.parse('{"title":"持续交付中的测试（下）—— 数据与质量","description":"","frontmatter":{},"headers":[],"relativePath":"testing/engineering/continuous-delivery-2/index.md","filePath":"测试理论与实践/4.现代测试工程/15.持续交付（下）.md","lastUpdated":1781625968000}'),l={name:"testing/engineering/continuous-delivery-2/index.md"};function n(r,t,o,h,d,p){return i(),s("div",null,[...t[0]||(t[0]=[e(`<h1 id="持续交付中的测试-下-——-数据与质量" tabindex="-1">持续交付中的测试（下）—— 数据与质量 <a class="header-anchor" href="#持续交付中的测试-下-——-数据与质量" aria-label="Permalink to &quot;持续交付中的测试（下）—— 数据与质量&quot;">​</a></h1><blockquote><p>管道搭好了、原则清楚了，但还有一个会被忽略的硬骨头——测试数据。数据脏了、不够了、和生产不一致了，再好的管道也产出不了可靠的测试结果。</p></blockquote><h2 id="测试数据-管道中最被低估的难题" tabindex="-1">测试数据：管道中最被低估的难题 <a class="header-anchor" href="#测试数据-管道中最被低估的难题" aria-label="Permalink to &quot;测试数据：管道中最被低估的难题&quot;">​</a></h2><p>测试代码可以版本控制、测试脚本可以自动化，但测试数据不行。<strong>数据是有状态的</strong>——你创建了一个订单，它就存在了；你删除了它，它就没了。下一次测试跑的时候，上次的脏数据还在不在？依赖的数据还在不在？</p><p>测试数据管理失败的典型表现：</p><ul><li>测试在本地能跑，在 CI 上跑挂——因为 CI 数据库里缺了某条数据</li><li>两个测试并行跑，互相踩了对方的数据——测试 A 删了测试 B 刚创建的记录</li><li>测试跑完后留下了脏数据，下次跑结果不一样——&quot;这个测试有时候过有时候挂&quot;</li></ul><p>下面三种策略，可以组合使用。</p><h3 id="策略一-每次都用全新的数据" tabindex="-1">策略一：每次都用全新的数据 <a class="header-anchor" href="#策略一-每次都用全新的数据" aria-label="Permalink to &quot;策略一：每次都用全新的数据&quot;">​</a></h3><p><strong>每个测试用例自己创建需要的数据，测完自己清理。</strong></p><p>这是最干净的方式——测试之间零依赖。缺点是实现成本高——你需要为每个测试写好数据的创建和清理逻辑。</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 测试：用户下单</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> test_create_order</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">():</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    user </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> create_test_user()      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 创建测试用户</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    product </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> create_test_product() </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 创建测试商品</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    order </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> api.create_order(user.id, product.id)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    assert</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> order.status </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;created&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    cleanup(user, product, order)   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 清理</span></span></code></pre></div><p>实践中常用&quot;工厂模式&quot;和&quot;Builder 模式&quot;来降低创建成本——写一套可复用的测试数据工厂，不同的测试用不同的参数调用它。</p><h3 id="策略二-共享快照" tabindex="-1">策略二：共享快照 <a class="header-anchor" href="#策略二-共享快照" aria-label="Permalink to &quot;策略二：共享快照&quot;">​</a></h3><p><strong>从一个固定的数据库快照启动，所有测试共享这个基础数据集。</strong></p><p>适合&quot;大部分测试需要相同的基础数据&quot;的场景——比如所有测试都假设&quot;系统中已有一个已注册用户、一个已上架商品&quot;。</p><ul><li><strong>优点</strong>：不用每个测试都写数据准备逻辑，快照还原一次就能跑</li><li><strong>缺点</strong>：测试会悄悄依赖快照里的具体数据——&quot;为什么这个测试突然失败了？&quot;→ 因为有人改了一条快照数据没通知你</li></ul><p>快照需要和代码一起维护——Schema 变了快照要重建、基础数据变了快照要更新。不是&quot;建一次放那三年&quot;。</p><h3 id="策略三-合成数据" tabindex="-1">策略三：合成数据 <a class="header-anchor" href="#策略三-合成数据" aria-label="Permalink to &quot;策略三：合成数据&quot;">​</a></h3><p><strong>用脚本或工具自动生成符合业务规则但不包含真实用户信息的数据。</strong></p><p>适合数据量测试和性能测试——需要海量数据时，手写数据准备脚本是灾难。用 Faker 之类的库生成随机但格式正确的姓名、邮箱、地址，配合一些关键业务数据手工定义。</p><h3 id="数据一致性-不要在生产数据上测试" tabindex="-1">数据一致性：不要在生产数据上测试 <a class="header-anchor" href="#数据一致性-不要在生产数据上测试" aria-label="Permalink to &quot;数据一致性：不要在生产数据上测试&quot;">​</a></h3><p>《持续交付》给了一条硬规则：<strong>测试环境不应该包含生产数据。</strong> 原因有三个：</p><ol><li>安全性——生产数据包含真实用户信息，泄露是安全事故</li><li>不可控——生产数据随真实用户行为变化，今天的测试依赖的数据明天可能被删了</li><li>环境差异——生产数据量和测试环境可能不匹配，导致性能测试结果不准确</li></ol><p>替代方案：用脱敏后的生产数据副本（但需要脱敏流程可靠），或者干脆用合成数据。</p><h2 id="自动化测试分层-让管道跑得动" tabindex="-1">自动化测试分层：让管道跑得动 <a class="header-anchor" href="#自动化测试分层-让管道跑得动" aria-label="Permalink to &quot;自动化测试分层：让管道跑得动&quot;">​</a></h2><p><a href="/testing/methodology/white-black-box.html">白盒与黑盒</a>讲了测试金字塔的概念，<a href="/testing/engineering/continuous-delivery-1.html">持续交付（上）</a>讲了管道各阶段。现在把两者结合起来——管道中的测试到底该怎么排。</p><h3 id="分层配置参考" tabindex="-1">分层配置参考 <a class="header-anchor" href="#分层配置参考" aria-label="Permalink to &quot;分层配置参考&quot;">​</a></h3><table tabindex="0"><thead><tr><th>管道阶段</th><th>主要测试</th><th>执行频率</th><th>并行策略</th></tr></thead><tbody><tr><td><strong>提交阶段</strong></td><td>小型测试（Q1）、lint、SAST</td><td>每次 git push</td><td>多核并行，5 分钟内必须跑完</td></tr><tr><td><strong>验收阶段</strong></td><td>中型验收测试（Q2）、DAST</td><td>每次提交通过后</td><td>按模块拆分并行</td></tr><tr><td><strong>容量阶段</strong></td><td>性能、压力、兼容性（Q4）</td><td>每日或按需</td><td>按测试类型并行</td></tr><tr><td><strong>手动阶段</strong></td><td>探索式测试（Q3）</td><td>每个迭代至少一次</td><td>多个测试人员分方向并行</td></tr></tbody></table><h3 id="让慢测试不阻塞管道" tabindex="-1">让慢测试不阻塞管道 <a class="header-anchor" href="#让慢测试不阻塞管道" aria-label="Permalink to &quot;让慢测试不阻塞管道&quot;">​</a></h3><p>验收阶段 1 小时的时间限制，对于大项目来说是一个真实的挑战。几个加速手段：</p><ul><li><strong>拆分套件</strong>：核心验收测试（每次提交跑）和全量验收测试（每日构建跑）分开</li><li><strong>并行执行</strong>：按模块拆分成独立套件，多台机器同时跑——前提是测试之间没有数据冲突</li><li><strong>只跑变更相关的测试</strong>：<a href="/testing/execution/regression-release.html">回归测试与上线标准</a>讲的选择性回归——结合影响分析，只跑本次改动可能影响的验收测试</li><li><strong>不稳定的测试踢出去</strong>：如果一个测试经常随机失败（flaky），先把它标记为待修复并踢出核心套件，等修好了再放回来。不要让它腐蚀管道的信任度</li></ul><h3 id="什么不该自动化" tabindex="-1">什么不该自动化 <a class="header-anchor" href="#什么不该自动化" aria-label="Permalink to &quot;什么不该自动化&quot;">​</a></h3><p>有些测试放管道里是浪费：</p><ul><li><strong>UI 的像素级验证</strong>：换一个浏览器、换一个屏幕分辨率，对不齐了——这种测试脆且维护成本高，不如人工看</li><li><strong>一次性验证的场景</strong>：就这一次需要确认的数据迁移、兼容性验证——写自动化脚本的时间比手工测还长</li><li><strong>需求还在快速变化的功能</strong>：脚本写了三天后需求变了——白写了</li></ul><blockquote><p>自动化不是目标，反馈速度才是。如果自动化一个测试需要 10 小时写脚本，但手工测只需要 30 分钟且一个迭代只做一次——不要自动化它。</p></blockquote><h2 id="质量内建-戴明的红珠实验" tabindex="-1">质量内建：戴明的红珠实验 <a class="header-anchor" href="#质量内建-戴明的红珠实验" aria-label="Permalink to &quot;质量内建：戴明的红珠实验&quot;">​</a></h2><p>《持续交付》里引用了一个关于质量的经典故事：戴明博士的<strong>红珠实验</strong>。</p><p>简单说：一个工厂里有一天出了很多次品。老板觉得是工人不努力，于是加了一道&quot;质检&quot;工序——每个产品出厂前检查一遍，次品扔掉。结果次品率没有降低，只是次品被发现得早了。问题不在质检，在<strong>上游的工序本身就有问题</strong>。</p><p>软件测试的同理——如果你加了很多测试人员发现了很多 bug，但没去改进开发过程，bug 还是会源源不断地生产出来。<strong>质量不能靠&quot;最后检查&quot;来获得，必须在每一步都内建进去。</strong></p><p>管道是实现质量内建的工程骨架：</p><ul><li>提交阶段的自动化检查 → 开发在提交之前就知道自己的代码能不能过</li><li>验收阶段的自动化 → 业务逻辑从写下第一行代码时就有用例在验证</li><li>容量阶段的自动化 → 性能从&quot;等上线压测&quot;变成了&quot;每次改代码都能看到趋势&quot;</li></ul><p>质量内建不要求你一开始就完美，但要求你<strong>每次发现一个漏掉的问题，就把对应的检查加进管道里</strong>。管道不是一成不变的——它随着团队的认知成长。今天在线上发现了一个 SQL 注入，明天 SAST 规则里就多一条检查；今天一个性能退化到上线才暴露，明天容量阶段就加一条基准比对。</p><h3 id="从-不要依赖检查-到-检查是最后的安全网" tabindex="-1">从&quot;不要依赖检查&quot;到&quot;检查是最后的安全网&quot; <a class="header-anchor" href="#从-不要依赖检查-到-检查是最后的安全网" aria-label="Permalink to &quot;从&quot;不要依赖检查&quot;到&quot;检查是最后的安全网&quot;&quot;">​</a></h3><p>戴明的名言是&quot;不要依赖大量检查来满足质量要求&quot;。这句话在持续交付中的实践解读是：</p><ul><li><strong>编写代码的时候</strong> → TDD、代码审查、静态分析——把问题消灭在编码阶段</li><li><strong>提交的时候</strong> → 提交阶段自动化——低级错误就地拦截</li><li><strong>验收的时候</strong> → 自动化验收——业务逻辑验证</li><li><strong>上线前</strong> → 容量阶段 + 手动阶段——最后的防线</li></ul><p>每一层都是安全网，但<strong>安全网不是让你随便掉下来的</strong>。最好的情况是第一层就抓住了问题，而不是层层掉到最后一层。</p><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><ol><li>测试数据有三种管理策略：每次重建（最干净）、共享快照（最方便）、合成数据（适合海量），可以组合使用</li><li>别在生产数据上测试——安全风险 + 数据不可控。用脱敏副本或合成数据替代</li><li>管道中的测试需要持续优化速度：拆套件、并行跑、选择性回归、踢出 flaky 测试</li><li>不是所有测试都适合自动化——一次性验证、快速变化的 UI、手工 30 秒能完成的检查，不需要写脚本</li><li>质量内建的实践：每次发现一个漏掉的问题，就在管道里加一条对应的检查——管道随着团队成长</li></ol>`,48)])])}const k=a(l,[["render",n]]);export{g as __pageData,k as default};
